<?php
declare(strict_types=1);
if(session_status()===PHP_SESSION_NONE)session_start();
require_once __DIR__.'/../../config/db.php';
require_once __DIR__.'/_quiz_lib.php';
if(!isset($_SESSION['academic_logged'])||$_SESSION['academic_logged']!==true){header('Location: /lessons/lessons/academic/login.php');exit;}
function tq_h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function tq_is_image($v):bool{$v=trim((string)$v);if($v==='')return false;if(str_starts_with($v,'data:image/'))return true;$p=(string)(parse_url($v,PHP_URL_PATH)??'');return(bool)preg_match('/\.(png|jpe?g|gif|webp|svg)$/i',$p);}
function tq_media($v,string $alt='',string $class='quiz-media'):string{$v=trim((string)$v);if($v==='')return'';return tq_is_image($v)?'<img class="'.tq_h($class).'" src="'.tq_h($v).'" alt="'.tq_h($alt).'" loading="eager">':tq_h($v);}
function tq_redirect(array $p):void{header('Location: teacher_viewer.php?'.http_build_query($p));exit;}
function tq_result_totals(array $quiz,array $answers):array{$s=qz_answers_totals($quiz,$answers);$qt=count($quiz);$cq=(int)($s['correct_questions']??0);$pp=max(0,(int)($s['possible']??0));$ep=max(0.0,min((float)$pp,(float)($s['earned']??0)));$pc=$pp>0?(int)round(($ep/$pp)*100):0;return['question_total'=>$qt,'correct_questions'=>$cq,'question_errors'=>max(0,$qt-$cq),'possible_points'=>$pp,'earned_points'=>$ep,'percent'=>max(0,min(100,$pc)),'skipped'=>max(0,(int)($s['skipped_questions']??0))];}
function tq_save_teacher_score(PDO $pdo,string $teacherId,string $assignmentId,string $unitId,array $r):void{$pdo->exec("CREATE TABLE IF NOT EXISTS teacher_unit_results (teacher_id TEXT NOT NULL,assignment_id TEXT NOT NULL,unit_id TEXT NOT NULL,completion_percent INTEGER NOT NULL DEFAULT 0,quiz_errors INTEGER NOT NULL DEFAULT 0,quiz_total INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY (teacher_id,assignment_id,unit_id))");$st=$pdo->prepare("INSERT INTO teacher_unit_results (teacher_id,assignment_id,unit_id,completion_percent,quiz_errors,quiz_total,updated_at) VALUES (:teacher_id,:assignment_id,:unit_id,:percent,:errors,:total,NOW()) ON CONFLICT (teacher_id,assignment_id,unit_id) DO UPDATE SET completion_percent=GREATEST(teacher_unit_results.completion_percent,EXCLUDED.completion_percent),quiz_errors=CASE WHEN EXCLUDED.completion_percent>=teacher_unit_results.completion_percent THEN EXCLUDED.quiz_errors ELSE teacher_unit_results.quiz_errors END,quiz_total=CASE WHEN EXCLUDED.completion_percent>=teacher_unit_results.completion_percent THEN EXCLUDED.quiz_total ELSE teacher_unit_results.quiz_total END,updated_at=NOW()");$st->execute(['teacher_id'=>$teacherId,'assignment_id'=>$assignmentId,'unit_id'=>$unitId,'percent'=>(int)$r['percent'],'errors'=>(int)$r['question_errors'],'total'=>(int)$r['question_total']]);}
function tq_append_result_to_return(string $returnTo,array $r):string{$t=trim($returnTo)!==''?$returnTo:'/lessons/lessons/academic/teacher_course.php';$sep=str_contains($t,'?')?'&':'?';return$t.$sep.http_build_query(['activity_total'=>(int)$r['question_total'],'activity_errors'=>(int)$r['question_errors'],'activity_percent'=>(int)$r['percent'],'activity_id'=>'unit_quiz','quiz_total'=>(int)$r['question_total'],'quiz_errors'=>(int)$r['question_errors'],'quiz_percent'=>(int)$r['percent']]);}
$assignmentId=trim((string)($_GET['assignment']??''));$unitId=trim((string)($_GET['unit']??''));$returnTo=trim((string)($_GET['return_to']??''));$mode=trim((string)($_GET['mode']??'intro'));$questionIndex=max(0,(int)($_GET['q']??0));$teacherId=trim((string)($_SESSION['teacher_id']??''));
if($assignmentId===''||$unitId===''||$teacherId===''){http_response_code(400);exit('Missing teacher, assignment, or unit information.');}
$st=$pdo->prepare('SELECT id FROM teacher_assignments WHERE id=:assignment AND teacher_id=:teacher LIMIT 1');$st->execute(['assignment'=>$assignmentId,'teacher'=>$teacherId]);if(!$st->fetchColumn()){http_response_code(403);exit('You do not have permission to open this quiz.');}
$st=$pdo->prepare('SELECT id,type,unit_id,data FROM activities WHERE unit_id::text=:unit ORDER BY id ASC');$st->execute(['unit'=>$unitId]);$activities=$st->fetchAll(PDO::FETCH_ASSOC)?:[];$allQuestions=[];foreach($activities as $activity){foreach(qz_normalize_activity($activity) as $question){if(($question['type']??'')!=='pronunciation')$allQuestions[]=$question;}}
if(!$allQuestions)exit('<div style="font-family:Arial;padding:30px;color:#7F77DD"><h2>No scoreable quiz questions were found for this unit.</h2></div>');
$baseKey='teacher_quiz_'.md5($teacherId.'|'.$assignmentId.'|'.$unitId);$attemptKey=$baseKey.'_attempt';$historyKey=$baseKey.'_history';if(!isset($_SESSION[$attemptKey]))$_SESSION[$attemptKey]=1;if(!isset($_SESSION[$historyKey])||!is_array($_SESSION[$historyKey]))$_SESSION[$historyKey]=[];$attempt=max(1,min(2,(int)$_SESSION[$attemptKey]));$quizKey=$baseKey.'_set_'.$attempt;$answersKey=$baseKey.'_answers_'.$attempt;if(!isset($_SESSION[$quizKey])||!is_array($_SESSION[$quizKey]))$_SESSION[$quizKey]=qz_build($allQuestions,$unitId,$assignmentId,$attempt);if(!isset($_SESSION[$answersKey])||!is_array($_SESSION[$answersKey]))$_SESSION[$answersKey]=[];$quiz=$_SESSION[$quizKey];$answers=&$_SESSION[$answersKey];$totalQuestions=count($quiz);
if(isset($_GET['restart'])&&$_GET['restart']==='1'){$last=$_SESSION[$historyKey][$attempt]??null;if($attempt<2&&is_array($last)&&(int)($last['percent']??100)<65){$_SESSION[$attemptKey]=2;unset($_SESSION[$baseKey.'_set_2'],$_SESSION[$baseKey.'_answers_2']);tq_redirect(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'intro']);}$mode='result';}
if($_SERVER['REQUEST_METHOD']==='POST'&&$mode==='quiz'){$questionIndex=max(0,min($questionIndex,$totalQuestions-1));if(!isset($answers[$questionIndex])){$q=$quiz[$questionIndex];if(isset($_POST['skip'])){$score=qz_answer_score($q,null);$answers[$questionIndex]=['answer'=>null,'skipped'=>true,'correct'=>false,'earned'=>0.0,'possible'=>$score['possible']];}else{$answer=in_array($q['type'],['match','drag_drop'],true)?(isset($_POST['answer'])&&is_array($_POST['answer'])?$_POST['answer']:[]):trim((string)($_POST['answer']??''));$score=qz_answer_score($q,$answer);$answers[$questionIndex]=['answer'=>$answer,'skipped'=>false,'correct'=>(bool)$score['correct'],'earned'=>(float)$score['earned'],'possible'=>(int)$score['possible']];}}if(count($answers)>=$totalQuestions)tq_redirect(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'result']);$next=$questionIndex+1;while($next<$totalQuestions&&isset($answers[$next]))$next++;tq_redirect(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'quiz','q'=>min($next,$totalQuestions-1)]);}
$result=tq_result_totals($quiz,$answers);$isComplete=count($answers)>=$totalQuestions;if($mode==='result'&&$isComplete){$_SESSION[$historyKey][$attempt]=$result;tq_save_teacher_score($pdo,$teacherId,$assignmentId,$unitId,$result);}$courseReturn=tq_append_result_to_return($returnTo,$result);$currentQuestion=$quiz[max(0,min($questionIndex,$totalQuestions-1))]??null;$canRetry=$isComplete&&$attempt<2&&(int)$result['percent']<65;
?>
<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unit Quiz</title><style>
:root{--purple:#7F77DD;--orange:#F97316;--line:#EDE9FA;--ink:#14113A;--muted:#8178B6;--bg:#F8F7FF}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Nunito,Arial,sans-serif;color:var(--ink)}.page{max-width:820px;margin:auto;padding:28px 18px 50px}.top,.card{background:#fff;border:1px solid var(--line);border-radius:24px;box-shadow:0 8px 28px rgba(127,119,221,.10)}.top{padding:16px 20px;margin-bottom:18px;display:flex;align-items:center;justify-content:space-between;gap:12px}.brand{font-weight:900;color:var(--purple)}.back,.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border:0;border-radius:12px;padding:12px 18px;font-weight:900;cursor:pointer}.back{background:#F0EEF8;color:var(--purple)}.card{padding:28px}.kicker{display:inline-block;background:#FFF0E6;color:#C2580A;border-radius:999px;padding:6px 13px;font-size:12px;font-weight:900}.title{font-size:34px;color:var(--orange);margin:12px 0}.lead{color:var(--muted);font-weight:700;line-height:1.5}.chips{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.chip{background:#F0EEF8;color:var(--purple);border-radius:999px;padding:7px 11px;font-size:12px;font-weight:900}.btn{background:var(--purple);color:#fff}.btn.orange{background:var(--orange)}.btn.light{background:#fff;color:var(--purple);border:1px solid var(--line)}.w100{width:100%}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.actions>*{flex:1;min-width:150px}.progress{height:9px;background:#EEEAF9;border-radius:999px;overflow:hidden;margin:10px 0 22px}.progress>div{height:100%;background:linear-gradient(90deg,var(--orange),var(--purple))}.question{font-size:23px;font-weight:900;line-height:1.4;margin:12px 0 12px}.question-media{display:flex;justify-content:center;margin:12px 0 18px}.quiz-media{display:block;max-width:100%;max-height:240px;object-fit:contain;border-radius:16px}.option{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid var(--line);border-radius:14px;margin:10px 0;font-weight:800;cursor:pointer}.option:has(input:checked){border-color:var(--purple);background:#F8F7FF}.option.image-option{align-items:flex-start}.option-image{display:block;max-width:100%;max-height:180px;object-fit:contain;margin:0 auto;border-radius:12px}.option-content{flex:1;min-width:0}.image-option .option-content{display:flex;justify-content:center}.input,.select{width:100%;padding:14px;border:1px solid var(--line);border-radius:12px;font:700 16px Nunito,Arial;margin:8px 0}.listen-box{display:flex;align-items:center;gap:12px;background:#F8F7FF;border:1px solid var(--line);border-radius:16px;padding:14px;margin:12px 0}.listen-btn{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:12px;padding:12px 18px;background:var(--purple);color:#fff;font-weight:900;cursor:pointer}.listen-btn.playing{background:var(--orange)}.listen-status{color:var(--muted);font-size:13px;font-weight:800}.match-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;align-items:center;margin:8px 0}.match-left{display:flex;align-items:center;gap:10px}.match-left img{max-width:120px;max-height:100px;object-fit:contain}.result{font-size:58px;font-weight:900;color:var(--orange);text-align:center}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{background:#F9F8FF;border:1px solid var(--line);border-radius:14px;padding:13px;text-align:center}.metric b{display:block;font-size:25px;color:var(--purple)}.review{border:1px solid var(--line);border-radius:14px;padding:13px;margin:10px 0}.good{color:#15803D}.bad{color:#B91C1C}@media(max-width:650px){.metric-grid{grid-template-columns:repeat(2,1fr)}.match-row{grid-template-columns:1fr}.actions{flex-direction:column}.actions>*{width:100%}}
</style></head><body><div class="page"><div class="top"><div class="brand">ONES · Teacher Quiz</div><a class="back" href="<?=tq_h($returnTo!==''?$returnTo:'/lessons/lessons/academic/teacher_course.php')?>">← Back</a></div>
<?php if($mode==='intro'):?><section class="card"><span class="kicker">UNIT QUIZ · ATTEMPT <?=$attempt?></span><h1 class="title">Accurate scoring</h1><p class="lead">The score is calculated from the points actually earned. Fill-in and writing questions may award partial credit by correctly positioned words. Pronunciation is excluded here because it cannot be scored accurately without speech validation.</p><div class="chips"><span class="chip"><?=$totalQuestions?> questions</span><span class="chip">Maximum 2 attempts</span><span class="chip">Retry below 65%</span></div><a class="btn orange w100" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'quiz','q'=>0]))?>">Start quiz</a></section>
<?php elseif($mode==='quiz'&&$currentQuestion):?><section class="card"><span class="kicker">QUESTION <?=$questionIndex+1?> OF <?=$totalQuestions?></span><div class="progress"><div style="width:<?=(int)round((($questionIndex+1)/max(1,$totalQuestions))*100)?>%"></div></div><div class="question"><?=tq_h((string)($currentQuestion['question']??'Answer the question.'))?></div><?php if(!empty($currentQuestion['image'])):?><div class="question-media"><?=tq_media($currentQuestion['image'],'Question image')?></div><?php endif;?><form method="post">
<?php if(($currentQuestion['type']??'')==='multiple_choice'):?><?php $imageOptions=((string)($currentQuestion['option_type']??''))==='image';foreach(($currentQuestion['options']??[])as$index=>$option):$isImg=$imageOptions||tq_is_image($option);?><label class="option<?=$isImg?' image-option':''?>"><input type="radio" name="answer" value="<?=(int)$index?>" required><span class="option-content"><?=$isImg?tq_media($option,'Option '.chr(65+$index),'option-image'):tq_h((string)$option)?></span></label><?php endforeach;?>
<?php elseif(($currentQuestion['type']??'')==='match'):?><?php $rights=array_column($currentQuestion['pairs']??[],'right');foreach(($currentQuestion['pairs']??[])as$index=>$pair):?><div class="match-row"><strong class="match-left"><?=tq_is_image($pair['left']??'')?tq_media($pair['left'],'Match item','option-image'):tq_h((string)($pair['left']??''))?></strong><select class="select" name="answer[<?=(int)$index?>]" required><option value="">Choose</option><?php foreach($rights as$right):?><option value="<?=tq_h((string)$right)?>"><?=tq_h((string)$right)?></option><?php endforeach;?></select></div><?php endforeach;?>
<?php elseif(($currentQuestion['type']??'')==='drag_drop'):?><p class="lead"><?=tq_h((string)($currentQuestion['instruction']??'Enter the words in the correct order.'))?></p><?php foreach(($currentQuestion['correct_words']??[])as$index=>$word):?><input class="input" name="answer[<?=(int)$index?>]" placeholder="Word <?=(int)$index+1?>" required><?php endforeach;?>
<?php elseif(($currentQuestion['type']??'')==='dictation'):?><div class="listen-box"><button class="listen-btn" type="button" data-audio="<?=tq_h((string)($currentQuestion['audio']??''))?>" data-text="<?=tq_h((string)($currentQuestion['correct']??''))?>">🔊 Listen</button><span class="listen-status">Listen, then type exactly what you hear.</span></div><input class="input" name="answer" autocomplete="off" required placeholder="Type what you hear">
<?php elseif(($currentQuestion['type']??'')==='fill'):?><input class="input" name="answer" required placeholder="Type the missing word or phrase">
<?php else:?><textarea class="input" name="answer" rows="3" required placeholder="Type your answer"></textarea><?php endif;?><div class="actions"><button class="btn orange" type="submit">Next</button><button class="btn light" type="submit" name="skip" value="1" formnovalidate>Skip</button></div></form></section>
<?php elseif($mode==='result'&&$isComplete):?><section class="card"><span class="kicker">ATTEMPT <?=$attempt?> RESULT</span><div class="result"><?=(int)$result['percent']?>%</div><div class="metric-grid"><div class="metric"><b><?=(int)$result['correct_questions']?></b>Correct questions</div><div class="metric"><b><?=(int)$result['question_errors']?></b>Questions with errors</div><div class="metric"><b><?=rtrim(rtrim(number_format((float)$result['earned_points'],2),'0'),'.')?></b>Points earned</div><div class="metric"><b><?=(int)$result['possible_points']?></b>Possible points</div></div><p class="lead" style="margin-top:18px">The percentage shown is earned points ÷ possible points.</p><div class="actions"><a class="btn light" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'review']))?>">Review answers</a><?php if($canRetry):?><a class="btn orange" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'restart'=>1]))?>">Second attempt</a><?php endif;?><a class="btn" href="<?=tq_h($courseReturn)?>">Save and return</a></div></section>
<?php elseif($mode==='review'&&$isComplete):?><section class="card"><span class="kicker">ANSWER REVIEW</span><h1 class="title"><?=(int)$result['percent']?>%</h1><?php foreach($quiz as$index=>$question):$answer=$answers[$index]??[];?><div class="review"><strong>Q<?=(int)$index+1?>. <?=tq_h((string)($question['question']??''))?></strong><div class="<?=!empty($answer['correct'])?'good':'bad'?>" style="margin-top:7px;font-weight:800"><?=!empty($answer['correct'])?'✓ Correct':'✗ Incorrect or partially correct'?> · <?=rtrim(rtrim(number_format((float)($answer['earned']??0),2),'0'),'.')?>/<?=(int)($answer['possible']??1)?> points</div><div style="margin-top:5px">Your answer: <?=tq_h(qz_review_answer_text($question,$answer['answer']??null))?></div><div>Correct answer: <?=tq_h(qz_review_correct_text($question))?></div></div><?php endforeach;?><div class="actions"><a class="btn" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'result']))?>">Back to result</a><a class="btn light" href="<?=tq_h($courseReturn)?>">Return to course</a></div></section>
<?php else:?><section class="card"><h1 class="title">Quiz incomplete</h1><p class="lead">Complete all questions before opening the result.</p><a class="btn orange" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'quiz','q'=>count($answers)]))?>">Continue quiz</a></section><?php endif;?></div><script>
(function(){
  var activeAudio=null;
  document.querySelectorAll('.listen-btn').forEach(function(button){
    button.addEventListener('click',function(){
      var audioUrl=(button.dataset.audio||'').trim();
      var text=(button.dataset.text||'').trim();
      if(activeAudio){activeAudio.pause();activeAudio.currentTime=0;activeAudio=null;}
      if('speechSynthesis' in window)window.speechSynthesis.cancel();
      button.classList.add('playing');button.textContent='🔊 Playing...';
      function reset(){button.classList.remove('playing');button.textContent='🔊 Listen';}
      if(audioUrl){
        activeAudio=new Audio(audioUrl);
        activeAudio.onended=reset;
        activeAudio.onerror=function(){activeAudio=null;if(text&&'speechSynthesis' in window){var u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.85;u.onend=reset;u.onerror=reset;window.speechSynthesis.speak(u);}else reset();};
        activeAudio.play().catch(function(){activeAudio.onerror();});
      }else if(text&&'speechSynthesis' in window){
        var utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=.85;utterance.onend=reset;utterance.onerror=reset;window.speechSynthesis.speak(utterance);
      }else reset();
    });
  });
})();
</script></body></html>
